import path from 'node:path';
import {lstat,readFile} from 'node:fs/promises';
import {codespacesOidcSettings} from './codespaces.mjs';

/** Load the identity fixture generated by dev:codespaces:setup. */
export async function codespacesPreviewLaunch(root,source=process.env){
 const expected=codespacesOidcSettings(source);
 const folder=path.join(root,'.local/identity-codespaces');
 const settingsFile=path.join(folder,'settings.json');
 const caFile=path.join(folder,'root.crt');
 let settingsInfo,caInfo;
 try{
  settingsInfo=await lstat(settingsFile);
  caInfo=await lstat(caFile);
 }catch(error){
  if(error.code==='ENOENT')throw Error('Codespaces identity is not configured. Run npm run dev:codespaces:setup after npm run dev:setup.');
  throw error;
 }
 if(!settingsInfo.isFile()||settingsInfo.isSymbolicLink()||(settingsInfo.mode&0o077))throw Error('Codespaces identity settings must be a private regular file.');
 if(!caInfo.isFile()||caInfo.isSymbolicLink()||caInfo.size===0)throw Error('Codespaces identity CA must be a non-empty regular file.');
 let settings;
 try{settings=JSON.parse(await readFile(settingsFile,'utf8'));}catch{throw Error('Invalid Codespaces identity settings. Rerun npm run dev:codespaces:setup.');}
 for(const [key,value] of Object.entries(expected))if(settings?.[key]!==value)throw Error('Codespaces identity settings do not match this workspace. Rerun npm run dev:codespaces:setup.');
 if(!/^dashboard_preview_[a-f0-9]{32}$/.test(settings.workspaceId??''))throw Error('Codespaces preview workspace ID is invalid. Rerun npm run dev:codespaces:setup.');
 return {
  env:{
   ...expected,
   DASHBOARD_DEVELOPMENT_CODESPACES:'true',
   DASHBOARD_DEVELOPMENT_CODESPACES_OIDC:'true',
   DASHBOARD_RELEASE_MODE:'BETA',
   DASHBOARD_BETA_WORKSPACE_IDS:settings.workspaceId,
   NODE_EXTRA_CA_CERTS:caFile
  },
  preload:['--import',path.join(root,'scripts/development/codespaces-fetch.mjs')],
  loginUrl:expected.DASHBOARD_PUBLIC_ORIGIN+'/dashboard/app/api/auth/login'
 };
}
